// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *SMTPSetup) FindSet() bool {
	// A temporary record reads all at once: its in-memory database has one connection, which
	// an open result set would block (Modify while looping)
	if t.temp != nil {
		return t.FindSetBuffered()
	}
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	tableName := SMTPSetupTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT primary_key, enabled, smtp_server, smtp_server_port, user_id, password, from_address FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for SMTP_Setup: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record in the result set
// Must be called after FindSet() or FindSetBuffered()
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (only with FindSetBuffered)
//   - Next(-3): Skip backward 3 records (only with FindSetBuffered)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *SMTPSetup) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var primary_keyNull sql.NullString
		var enabledBool sql.NullBool
		var smtp_serverNull sql.NullString
		var user_idNull sql.NullString
		var passwordNull sql.NullString
		var from_addressNull sql.NullString

		err := t.currentRows.Scan(
			&primary_keyNull,
			&enabledBool,
			&smtp_serverNull,
			&t.Smtp_server_port,
			&user_idNull,
			&passwordNull,
			&from_addressNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan SMTP_Setup record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.Primary_key = types.NewCode(primary_keyNull.String)
		t.Enabled = enabledBool.Bool
		t.Smtp_server = types.NewText(smtp_serverNull.String)
		t.User_id = types.NewText(user_idNull.String)
		t.Password = types.NewText(passwordNull.String)
		t.From_address = types.NewText(from_addressNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No active recordset
	return false
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *SMTPSetup) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := SMTPSetupTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT primary_key, enabled, smtp_server, smtp_server_port, user_id, password, from_address FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for SMTP_Setup: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &SMTPSetup{}
		record.db = t.db
		record.temp = t.temp
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var primary_keyNull sql.NullString
		var enabledBool sql.NullBool
		var smtp_serverNull sql.NullString
		var user_idNull sql.NullString
		var passwordNull sql.NullString
		var from_addressNull sql.NullString

		err := rows.Scan(
			&primary_keyNull,
			&enabledBool,
			&smtp_serverNull,
			&record.Smtp_server_port,
			&user_idNull,
			&passwordNull,
			&from_addressNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan SMTP_Setup record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.Primary_key = types.NewCode(primary_keyNull.String)
		record.Enabled = enabledBool.Bool
		record.Smtp_server = types.NewText(smtp_serverNull.String)
		record.User_id = types.NewText(user_idNull.String)
		record.Password = types.NewText(passwordNull.String)
		record.From_address = types.NewText(from_addressNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate SMTP_Setup records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
func (t *SMTPSetup) copyFromBuffered(record *SMTPSetup) {
	t.Primary_key = record.Primary_key
	t.Enabled = record.Enabled
	t.Smtp_server = record.Smtp_server
	t.Smtp_server_port = record.Smtp_server_port
	t.User_id = record.User_id
	t.Password = record.Password
	t.From_address = record.From_address
	t.StoreOldValues()
}

